{"path": "schema_postgres.sql", "content": "-- PostgreSQL 15+ schema: events (weekly range partitions), dashboards (JSONB widgets), RLS option
CREATE TABLE events (
  event_id    bigint        NOT NULL,
  tenant_id   text          NOT NULL,
  occurred_at timestamptz   NOT NULL,
  event_type  text          NOT NULL,
  user_id     text          NOT NULL,
  session_id  text          NOT NULL,
  properties  jsonb         NOT NULL DEFAULT '{}',
  amount      numeric(12,2),
  PRIMARY KEY (tenant_id, occurred_at, event_id)      -- must contain partition key
) PARTITION BY RANGE (occurred_at);

DO $$ DECLARE d date := date '2026-07-20'; BEGIN   -- 14 weekly partitions cover 2026-07-22..2026-10-22
  WHILE d < date '2026-10-30' LOOP
    EXECUTE format('CREATE TABLE events_%s PARTITION OF events FOR VALUES FROM (%L) TO (%L)',
                   to_char(d,'YYYYMMDD'), d, d + 7);
    d := d + 7;
  END LOOP;
END $$;

CREATE INDEX events_tenant_time ON events (tenant_id, occurred_at DESC);          -- Q1,Q2,Q3,Q4
CREATE INDEX events_tenant_type_time ON events (tenant_id, event_type, occurred_at); -- Q3/Q5 selective
CREATE INDEX events_props_gin ON events USING gin (properties jsonb_path_ops);    -- Q5 containment
CREATE INDEX events_time_brin ON events USING brin (occurred_at) WITH (pages_per_range=32);

CREATE TABLE dashboards (
  dashboard_id bigint PRIMARY KEY,
  tenant_id    text NOT NULL,
  name         text NOT NULL,
  owner        text NOT NULL,
  widgets      jsonb NOT NULL DEFAULT '[]',   -- [{widget_id,type,query_def,layout}]
  updated_at   timestamptz NOT NULL,
  CHECK (jsonb_typeof(widgets) = 'array')
);
CREATE INDEX dashboards_tenant ON dashboards (tenant_id, updated_at DESC);

-- Tenant isolation option: shared tables + row-level security (enable for isolation test; costs measured separately)
ALTER TABLE events     ENABLE ROW LEVEL SECURITY;
ALTER TABLE dashboards ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_iso_e ON events     USING (tenant_id = current_setting('app.tenant_id', true));
CREATE POLICY tenant_iso_d ON dashboards USING (tenant_id = current_setting('app.tenant_id', true));
-- app role (non-owner, no BYPASSRLS) must be used for queries: CREATE ROLE app LOGIN; GRANT SELECT,INSERT ON events,dashboards TO app;
"}

{"path": "pg_bench.py", "content": "#!/usr/bin/env python3
"""Benchmark PostgreSQL. Usage: python3 pg_bench.py "dbname=bench user=postgres host=/tmp" data
Needs psycopg2 + running server. Loads data/events.csv + data/dashboards.jsonl via COPY, runs Q1-Q7 (60 warm runs each),
then 80/20 read/write mixed workload at concurrency 8/32/84 for 20 s each. Writes results_postgres.json."""
import sys, os, json, time, random, threading, statistics, platform, datetime as dt
import psycopg2
DSN, D = sys.argv[1], sys.argv[2]
NOW = "timestamptz '2026-10-22 00:00:00+00'"
Q = {
 "Q1": f"SELECT date_trunc('hour',occurred_at) h,event_type,count(*) FROM events WHERE tenant_id=%s AND occurred_at>={NOW}-interval '24 hours' GROUP BY 1,2",
 "Q2": f"SELECT date_trunc('day',occurred_at) d,count(DISTINCT user_id) FROM events WHERE tenant_id=%s AND occurred_at>={NOW}-interval '30 days' GROUP BY 1",
 "Q3": f"SELECT event_type,count(*) c FROM events WHERE tenant_id=%s AND occurred_at>={NOW}-interval '7 days' GROUP BY 1 ORDER BY c DESC LIMIT 10",
 "Q4": f"""WITH s AS (SELECT session_id,min(occurred_at) FILTER (WHERE event_type='view') v,min(occurred_at) FILTER (WHERE event_type='add_to_cart') c,
   min(occurred_at) FILTER (WHERE event_type='purchase') p FROM events WHERE tenant_id=%s AND occurred_at>={NOW}-interval '7 days' GROUP BY 1)
   SELECT count(*) FILTER (WHERE v IS NOT NULL),count(*) FILTER (WHERE c>v),count(*) FILTER (WHERE p>c AND c>v) FROM s""",
 "Q5": f"""SELECT date_trunc('day',occurred_at) d,sum(amount) FROM events WHERE tenant_id=%s AND occurred_at>={NOW}-interval '30 days'
   AND properties @> '{{"plan":"pro","channel":"web"}}' GROUP BY 1""",
 "Q6": "SELECT dashboard_id,name,owner,widgets,updated_at FROM dashboards WHERE tenant_id=%s ORDER BY updated_at DESC LIMIT 1",
}
def conn():
    c = psycopg2.connect(DSN); c.autocommit = True; return c
def tenant(r):  # skewed pick, same Zipf-ish as generator
    return "t%02d" % min(49, int(r.paretovariate(0.7)) - 1) if r.random() < .5 else "t%02d" % r.randrange(50)
nid = [10**9]; lock = threading.Lock()
def q7(cur, r):
    with lock: base = nid[0]; nid[0] += 1000
    t = tenant(r)
    rows = [(base + i, t, "2026-10-21 12:00:00+00", "view", "u%d" % r.randrange(10000), "%s-s%d" % (t, r.randrange(1000)),
             json.dumps({"plan": "pro", "channel": "web", "device": {"os": "a"}}), 9.5) for i in range(1000)]
    args = b",".join(cur.mogrify("(%s,%s,%s,%s,%s,%s,%s::jsonb,%s)", x) for x in rows)
    cur.execute(b"INSERT INTO events VALUES " + args)
def run(cur, name, r):
    if name == "Q7": q7(cur, r)
    else: cur.execute(Q[name], (tenant(r),)); cur.fetchall()
def pct(a, p): a = sorted(a); return round(a[min(len(a) - 1, int(len(a) * p))] * 1000, 3)
res = {"status": "EXECUTED", "environment": {"python": platform.python_version(), "os": platform.platform(), "cpus": os.cpu_count(),
       "psycopg2": psycopg2.__version__}}
c = conn(); cur = c.cursor(); cur.execute("select version()"); res["environment"]["server"] = cur.fetchone()[0]
cur.execute(open("schema_postgres.sql").read())
t0 = time.time()
with open(f"{D}/events.csv") as f: cur.copy_expert("COPY events(event_id,tenant_id,occurred_at,event_type,user_id,session_id,properties,amount) FROM STDIN CSV", f)
for l in open(f"{D}/dashboards.jsonl"):
    d = json.loads(l); cur.execute("INSERT INTO dashboards VALUES (%s,%s,%s,%s,%s,%s)", (d["dashboard_id"], d["tenant_id"], d["name"], d["owner"], json.dumps(d["widgets"]), d["updated_at"]))
cur.execute("ANALYZE"); res["load_seconds"] = round(time.time() - t0, 2)
cur.execute("select count(*) from events"); res["rows_events"] = cur.fetchone()[0]
cur.execute("select count(*) from dashboards"); res["rows_dashboards"] = cur.fetchone()[0]
cur.execute("select coalesce(sum(pg_total_relation_size(c.oid)),0), coalesce(sum(pg_table_size(c.oid)),0) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p') and c.relname like 'events%'")
tot, heap = cur.fetchone(); raw = os.path.getsize(f"{D}/events.jsonl")
res["bytes_on_disk_events_incl_indexes"] = int(tot); res["bytes_on_disk_events_heap_only"] = int(heap); res["raw_bytes_jsonl"] = raw
res["ratio_disk_to_raw_incl_indexes"] = round(tot / raw, 3); res["ratio_heap_to_raw"] = round(heap / raw, 3)
r = random.Random(42); res["per_query_ms"] = {}
for name in ["Q1", "Q2", "Q3", "Q4", "Q5", "Q6", "Q7"]:
    for _ in range(5): run(cur, name, r)       # warm-up
    lat = []
    for _ in range(60):
        t = time.perf_counter(); run(cur, name, r); lat.append(time.perf_counter() - t)
    res["per_query_ms"][name] = {"runs": 60, "p50": pct(lat, .5), "p95": pct(lat, .95), "p99": pct(lat, .99)}
def worker(stop, out, seed):
    cc = conn(); cu = cc.cursor(); rr = random.Random(seed); n = 0
    while time.time() < stop:
        name = "Q7" if rr.random() < .2 else rr.choice(["Q1", "Q2", "Q3", "Q4", "Q5", "Q6"])
        try: run(cu, name, rr); n += 1
        except Exception: out.append(-1)
    out.append(n); cc.close()
res["mixed_80_20_throughput"] = {}
for k in (8, 32, 84):
    out = []; stop = time.time() + 20
    th = [threading.Thread(target=worker, args=(stop, out, 1000 + i)) for i in range(k)]
    [t.start() for t in th]; [t.join() for t in th]
    ok = sum(x for x in out if x > 0); res["mixed_80_20_throughput"][str(k)] = {"ops_per_sec": round(ok / 20, 1), "errors": out.count(-1)}
res["note"] = "Single-node small-scale run; does not prove 10 TB behaviour."
json.dump(res, open("results_postgres.json", "w"), indent=1); print(json.dumps(res, indent=1))
"}

