    "occurred_at": {"bsonType": "date"}, "event_type": {"bsonType": "string"},
    "user_id": {"bsonType": "string"}, "session_id": {"bsonType": "string"},
    "properties": {"bsonType": "object"},
    "amount": {"bsonType": ["double", "decimal", "int", "long", "null"]}}}}
